catalog_ui_policy.script_false:
function onCondition() {
    var fields = g_form.getEditableFields();
    for (var i = 0; i < fields.length; i++) {
        g_form.setDisabled(fields[i], false);
    }
}

catalog_ui_policy.script_true:
function onCondition() {
    var fields = g_form.getEditableFields();
    for (var i = 0; i < fields.length; i++) {
        g_form.setDisabled(fields[i], true);
    }

}
